//! QC-LDPC base graphs (§8.2, spec open decision #4).
//!
//! **Generated by `cargo run -p xtask -- ldpc`. Do not edit by hand.**
//!
//! Two families of base graph per rate. The large family (`n_b = 60`) is used
//! wherever the layer is long enough to lift it; the small family (`n_b = 20`)
//! covers short layers — a v1 `C2` chroma layer is 26 bits, which cannot lift a
//! 60-column graph to a positive information length at all.
//!
//! Rows come from progressive edge growth over the base graph, with the
//! bidiagonal parity structure fixed first so the information edges are placed
//! around it. Shifts are chosen greedily to minimise four-cycles across the
//! spread of lift sizes the format actually uses, since `shift(Z) = shift₀ mod Z`
//! makes cycle structure lift-dependent.

/// Information-column degree of every base graph.
pub const DV: usize = 3;

/// One information column: `DV` `(base row, shift)` pairs.
pub type Column = [(u8, u16); DV];

/// A quasi-cyclic base graph. Columns `0..k_b` are information, `k_b..n_b` parity.
#[derive(Clone, Copy, Debug)]
pub struct BaseGraph {
    /// Total base columns.
    pub n_b: usize,
    /// Information base columns.
    pub k_b: usize,
    /// Check base rows, `n_b − k_b`.
    pub m_b: usize,
    /// Incidence and shifts of the information columns.
    pub info: &'static [Column],
}

